ext('c12_geo_ch9',[
C("🇮🇳","भारत की जनसंख्या: आँकड़े",["विश्व में दूसरा/पहला बड़ा देश","लगभग 17% विश्व आबादी","क्षेत्रफल केवल लगभग 2.4%","घनत्व बहुत अधिक"],"भारत विश्व के सबसे अधिक आबादी वाले देशों में है, और हाल के अनुमानों में यह पहले स्थान पर पहुँच गया है। विश्व की लगभग सत्रह प्रतिशत आबादी यहाँ रहती है, जबकि क्षेत्रफल केवल लगभग दो दशमलव चार प्रतिशत है। इसीलिए जनसंख्या का घनत्व बहुत अधिक है। इतनी बड़ी आबादी के लिए भोजन, शिक्षा, स्वास्थ्य और रोज़गार की व्यवस्था करना एक बड़ी चुनौती और अवसर दोनों है।"),
Q("भारत में जनगणना कौन करवाता है?","भारत के महापंजीयक एवं जनगणना आयुक्त का कार्यालय, गृह मंत्रालय के अंतर्गत","याद कीजिए... जनगणना गृह मंत्रालय के अधीन भारत के महापंजीयक एवं जनगणना आयुक्त करवाते हैं। यह हर दस साल में की जाती है और इससे जनसंख्या, साक्षरता, लिंगानुपात जैसे आँकड़े मिलते हैं।"),
C("🗺️","जनसंख्या का वितरण",["उत्तर प्रदेश: सबसे अधिक","सिक्किम: सबसे कम","बिहार: सबसे घना राज्य","गंगा का मैदान: घना"],"भारत में जनसंख्या का वितरण असमान है। उत्तर प्रदेश सबसे अधिक आबादी वाला राज्य है, जबकि सिक्किम सबसे कम आबादी वाला। घनत्व में बिहार का स्थान ऊपर है, क्योंकि यहाँ उपजाऊ गंगा का मैदान है। पहाड़ी राज्य, रेगिस्तान और जंगलों वाले क्षेत्र विरल आबादी वाले हैं। नदी घाटियाँ और तटीय मैदान घने बसे हैं। यानी भूमि, पानी और जलवायु ही आबादी का वितरण तय करते हैं।"),
Q("भारत में सबसे घने बसे राज्यों में बिहार का नाम क्यों आता है?","उपजाऊ गंगा के मैदान, पर्याप्त पानी और कृषि योग्य भूमि के कारण","कारण सोचिए... गंगा के मैदान की मिट्टी उपजाऊ है और पानी की कमी नहीं। खेती से बड़ी आबादी का पेट पल सकता है। इसलिए बिहार और आसपास के क्षेत्र घने बसे हैं।"),
C("📈","जनसंख्या वृद्धि के चरण",["1901–1921: स्थिर चरण","1921–1951: मंद वृद्धि","1951–1981: तेज़ वृद्धि","1981 के बाद: धीमी होती दर"],"भारत की जनसंख्या वृद्धि को चार चरणों में समझा जाता है। उन्नीस सौ एक से इक्कीस तक वृद्धि लगभग रुकी रही। इक्कीस से इक्यावन के बीच यह मंद रही। इक्यावन से इक्यासी तक स्वास्थ्य सुधारों से मृत्यु दर घटी, इसलिए वृद्धि तेज़ रही। उन्नीस सौ इक्यासी के बाद वृद्धि दर धीरे-धीरे घटने लगी, हालाँकि कुल संख्या अब भी बढ़ रही है। इन चरणों का नाम और अवधि याद रखिए।"),
Q("1951 से 1981 के बीच जनसंख्या तेज़ी से क्यों बढ़ी?","मृत्यु दर घटी (स्वास्थ्य और स्वच्छता में सुधार) जबकि जन्म दर ऊँची बनी रही","सोचिए... टीके, अस्पताल और अकाल पर नियंत्रण से मृत्यु दर घट गई। पर जन्म दर लगभग वैसी ही रही। इसी अंतर से जनसंख्या तेज़ी से बढ़ी। इसे जनसंख्या विस्फोट भी कहते हैं।"),
C("👶","आयु संरचना और जनसांख्यिकीय लाभांश",["0–14: बच्चे","15–59: कार्यशील","60+: वृद्ध","युवा आबादी भारत की ताक़त"],"भारत एक युवा देश है। यहाँ पंद्रह से उनसठ वर्ष के कार्यशील लोगों का अनुपात बहुत अधिक है। इससे जनसांख्यिकीय लाभांश का अवसर मिलता है, यानी कमाने वाले ज़्यादा और आश्रित कम। पर इसका लाभ तभी मिलेगा जब युवाओं को अच्छी शिक्षा, कौशल और रोज़गार मिले। वरना यही आबादी बेरोज़गारी के रूप में बोझ बन सकती है। आने वाले दशकों में वृद्ध आबादी का अनुपात भी बढ़ेगा।"),
Q("जनसांख्यिकीय लाभांश का लाभ लेने के लिए क्या ज़रूरी है?","युवाओं की शिक्षा, कौशल विकास और रोज़गार के अवसर","सोचिए... केवल युवा होना काफ़ी नहीं। उन्हें पढ़ाई, हुनर और नौकरी भी मिलनी चाहिए। तभी वे देश की अर्थव्यवस्था को आगे बढ़ा पाएँगे।"),
C("⚤","लिंगानुपात और साक्षरता",["लिंगानुपात: प्रति 1000 पुरुष पर महिलाएँ","2011: 943","केरल सर्वाधिक","साक्षरता: लगभग 74%"],"लिंगानुपात का अर्थ है प्रति एक हज़ार पुरुषों पर महिलाओं की संख्या। दो हज़ार ग्यारह की जनगणना के अनुसार यह नौ सौ तैंतालीस था। केरल का लिंगानुपात सबसे अच्छा है और हरियाणा जैसे राज्यों में कम है। साक्षरता उसी जनगणना में लगभग चौहत्तर प्रतिशत थी, जिसमें महिला साक्षरता पुरुषों से कम थी। बेटी बचाओ, बेटी पढ़ाओ जैसी योजनाएँ इस अंतर को घटाने के लिए हैं।"),
Q("लिंगानुपात किसे कहते हैं?","प्रति 1000 पुरुषों पर महिलाओं की संख्या","परिभाषा याद कीजिए... लिंगानुपात में पुरुषों को एक हज़ार मानकर देखा जाता है कि उनके मुक़ाबले कितनी महिलाएँ हैं। यह समाज में लैंगिक समानता का संकेतक है।"),
C("🏘️","ग्रामीण और नगरीय जनसंख्या",["अधिकांश आबादी गाँव में","नगरीकरण बढ़ रहा","महानगरों पर दबाव","प्रवास का बढ़ना"],"भारत की अधिकांश आबादी अब भी गाँवों में रहती है, पर नगरीकरण तेज़ी से बढ़ रहा है। रोज़गार और सुविधाओं की तलाश में लोग शहरों की ओर जा रहे हैं। इससे महानगरों में झुग्गियाँ, भीड़ और प्रदूषण जैसी समस्याएँ बढ़ती हैं। इसलिए गाँवों में रोज़गार, शिक्षा और स्वास्थ्य सुविधाएँ बढ़ाना ज़रूरी है ताकि प्रवास का दबाव घटे और संतुलित विकास हो।"),
C("📋","राष्ट्रीय जनसंख्या नीति",["परिवार नियोजन","लड़कियों की शिक्षा","स्वास्थ्य सेवाएँ","जागरूकता अभियान"],"भारत ने जनसंख्या नियंत्रण के लिए परिवार नियोजन कार्यक्रम बहुत पहले शुरू किया था। राष्ट्रीय जनसंख्या नीति में स्वास्थ्य सेवाओं के विस्तार, शिशु और मातृ मृत्यु दर घटाने, लड़कियों की शिक्षा बढ़ाने और विवाह की आयु बढ़ाने पर ज़ोर है। जागरूकता अभियानों से लोगों को छोटे परिवार के लाभ बताए जाते हैं। अनुभव कहता है कि शिक्षा, ख़ासकर महिलाओं की, जनसंख्या नियंत्रण का सबसे प्रभावी साधन है।"),
Q("जनसंख्या नियंत्रण में महिला शिक्षा की क्या भूमिका है?","शिक्षित महिलाएँ देर से विवाह करती हैं, परिवार नियोजन अपनाती हैं और जन्म दर घटती है","सोचिए... पढ़ी-लिखी महिलाएँ अपने स्वास्थ्य और बच्चों के बारे में बेहतर निर्णय लेती हैं। इससे विवाह की आयु बढ़ती है और जन्म दर घटती है। इसलिए शिक्षा को सबसे असरदार उपाय माना जाता है।"),
C("✍️","उत्तर लिखने की रणनीति",["आँकड़े सही लिखें","तालिका और रेखाचित्र","चरणों के नाम","संतुलित निष्कर्ष"],"इस अध्याय में आँकड़ों की भूमिका बड़ी है, इसलिए जनगणना के मुख्य आँकड़े याद रखिए, जैसे लिंगानुपात और साक्षरता। जनसंख्या वृद्धि के चरणों को समय-रेखा के रूप में बनाइए। दीर्घ उत्तर में कारण, समस्याएँ और उपाय अलग-अलग शीर्षकों में लिखिए। भारत के मानचित्र पर सबसे घने और सबसे विरल राज्य चिह्नित करने से अंक बढ़ते हैं। अंत में निष्कर्ष दीजिए कि संख्या के साथ गुणवत्ता पर भी ध्यान ज़रूरी है।"),
],7)
